use erpx_service::service_initial_physical_stock_transport::*;
#[cfg(feature="field-service-http")]
use erpx_server_shared::public::{CompanyId,HoldingId};
use facts::*;
struct Ids;
impl IdentifierSource for Ids {
    fn next(&mut self) -> RecordId {
        RecordId::new(uuid::Uuid::new_v4().to_string()).unwrap()
    }
}
struct ExpiringIds {
    clock: std::sync::Arc<account::fixture::MutableClock>,
    advanced: bool,
}
impl IdentifierSource for ExpiringIds {
    fn next(&mut self) -> RecordId {
        if !self.advanced {
            self.clock.advance(3_600_001);
            self.advanced = true;
        }
        RecordId::new(uuid::Uuid::new_v4().to_string()).unwrap()
    }
}
fn environment() -> ServiceInitialPhysicalStockEnvironment {
    static ENV: std::sync::OnceLock<ServiceInitialPhysicalStockEnvironment> =
        std::sync::OnceLock::new();
    ENV.get_or_init(|| {
        ServiceInitialPhysicalStockEnvironment::new(
            InitialCountModuleMode::Development,
            "synthetic-field-test".into(),
            None,
        )
    })
    .clone()
}
#[cfg(feature="field-service-http")]
fn target(clock: std::sync::Arc<account::fixture::MutableClock>) -> ServiceInitialCountTarget<account::fixture::MutableClock> {
 ServiceInitialCountTarget { holding:HoldingId::new("h001").unwrap(),company:CompanyId::new("company").unwrap(),clock,environment:environment(),files_features:CountBindingFeatures{enabled:true,read_only:false,uploads_frozen:false} }
}
#[cfg(feature="field-service-http")]
fn count_http(method:&str,path:&str,cookie:&str,key:Option<&str>,body:String)->axum::http::Request<axum::body::Body> {
 let mut r=axum::http::Request::builder().method(method).uri(path).header("host","acme.example.test").header("origin","https://acme.example.test").header("cookie",cookie).header("x-erpx-context-company","company").header("x-erpx-context-revision","8").header("x-erpx-context-assignment","field-fixture-a").header("x-erpx-context-assignment-version","3");if let Some(k)=key{r=r.header("idempotency-key",k);}r.body(axum::body::Body::from(body)).unwrap()
}
#[cfg(feature="field-service-http")]
async fn count_http_raw(router:&axum::Router,request:axum::http::Request<axum::body::Body>)->(axum::http::StatusCode,String) {
 use tower::ServiceExt;let response=router.clone().oneshot(request).await.unwrap();let status=response.status();assert_eq!(response.headers().get("cache-control").and_then(|v|v.to_str().ok()),Some("private, no-store"));let bytes=axum::body::to_bytes(response.into_body(),2*1024*1024).await.unwrap();(status,String::from_utf8(bytes.to_vec()).unwrap())
}
#[cfg(feature="field-service-http")]
async fn count_http_response(router:&axum::Router,request:axum::http::Request<axum::body::Body>)->(axum::http::StatusCode,serde_json::Value) {let (status,body)=count_http_raw(router,request).await;(status,serde_json::from_str(&body).unwrap())}

fn access() -> WorkAuthorizationRequest {
    WorkAuthorizationRequest {
        permission: "inventory.read".into(),
        module: None,
        destination: "services/field-service".into(),
        api: true,
    }
}
fn sources() -> ServiceInitialPhysicalStockSources {
    environment().sources()
}

